#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    long long q;
    cin >> n >> q;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    vector<vector<long long>> ops(q, vector<long long>(2));
    for (int i = 0; i < q; i++) {
        for (int j = 0; j < 2; j++) {
            cin >> ops[i][j];
        }
    }

    long long size = 1;
    while (size < n) size *= 2;
    vector<long long> tree(2 * size, 0), state = a;
    for (long long i = 0; i < n; i++) tree[size + i] = a[i];
    for (long long v = size - 1; v >= 1; v--) tree[v] = tree[2 * v] + tree[2 * v + 1];
    string out;
    for (long long i = 0; i < q; i++) {
        long long kind = ops[i][0], x = ops[i][1];
        if (kind == 1) {
            long long delta = 1 - 2 * state[x - 1];
            state[x - 1] ^= 1;
            for (long long v = size + x - 1; v >= 1; v /= 2) tree[v] += delta;
        } else {
            long long k = x, result;
            if (tree[1] < k) {
                result = -1;
            } else {
                long long v = 1;
                while (v < size) {
                    if (tree[2 * v] >= k) {
                        v = 2 * v;
                    } else {
                        k -= tree[2 * v];
                        v = 2 * v + 1;
                    }
                }
                result = v - size + 1;
            }
            if (!out.empty()) out += " ";
            out += to_string(result);
        }
    }
    cout << out << "\n";

    return 0;
}

